text(await tools.exec_command({cmd:"pwd && rg --files -g 'AGENTS.md' -g 'REQUIREMENTS.md' -g '*interview-E-1*' -g '*TRACKER*' -g '*PLAN*' -g '*manifest*'","max_output_tokens":3000}));
text(await tools.clock__curr_time({}));
text(ALL_TOOLS.filter(x=>/search|browse|fetch/.test(x.name+" "+x.description)).map(x=>({name:x.name,description:x.description.slice(0,150)})));

const results = await Promise.allSettled([
tools.exec_command({cmd:"cat AGENTS.md REQUIREMENTS.md interviews/interview-E-1.md","max_output_tokens":14000}),
tools.exec_command({cmd:"rg --files -g '!node_modules' -g '!.git'","max_output_tokens":5000}),
tools.exec_command({cmd:"git status --short","max_output_tokens":1000}),
]);
results.forEach(text);

const r=await Promise.allSettled([
tools.exec_command({cmd:"cat /home/mike/.codex/plugins/cache/openai-curated-remote/google-drive/0.1.22/skills/google-drive/SKILL.md","max_output_tokens":7000}),
tools.exec_command({cmd:"cat README.md snapshot.schema.json","max_output_tokens":15000})
]);r.forEach(text);
text(ALL_TOOLS.filter(x=>/google_drive_fetch$|google_drive_search$/.test(x.name)));

